    "seo_title": "HPV DNA Test in Bengaluru | QXL Diagnostics",
    "meta_description": "HPV DNA: purpose, preparation, samples and result interpretation. Ask QXL Bengaluru for current price, report time and collection.",
    "canonical_url": "https://qxldiagnostics.com/blog/high-risk-hpv-dna-bengaluru-guide",
