    "seo_title": "Pap Smear & LBC Test in Bengaluru | QXL Diagnostics",
    "meta_description": "Pap Smear & LBC: purpose, preparation, samples and result interpretation. Ask QXL Bengaluru for current price, report time and collection.",
    "canonical_url": "https://qxldiagnostics.com/blog/pap-smear-liquid-based-cytology-bengaluru-guide",
